draw:
const L = 1.0;                    // block length in units
const over2 = p.top;              // overhang of top block past the lower block, in units of L
const over1 = p.bottom;           // overhang of lower block past the table, in units of L

const scale = W * 0.30;           // pixels per block length
const tableX = W * 0.44;          // table edge
const bh = Math.max(16, H * 0.13);
const baseY = H * 0.72;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// table
ctx.fillStyle = C.faint;
ctx.fillRect(20, baseY, tableX - 20, H * 0.20);
ctx.fillStyle = C.ink;
ctx.fillText("table", (20 + tableX) / 2, baseY + H * 0.14);

// lower block: left end at tableX - (1 - over1)*scale
const x1 = tableX - (L - over1) * scale;
const x2 = x1 + over2 * scale;    // top block shifted further right
ctx.fillStyle = C.figure;
ctx.fillRect(x1, baseY - bh, L * scale, bh);
ctx.fillRect(x2, baseY - 2 * bh - 2, L * scale, bh);

// centres of mass
const c1 = x1 + 0.5 * scale, c2 = x2 + 0.5 * scale;
const cpair = (c1 + c2) / 2;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(c1, baseY - bh / 2, 4, 0, 6.284); ctx.fill();
ctx.beginPath(); ctx.arc(c2, baseY - 1.5 * bh - 2, 4, 0, 6.284); ctx.fill();

// combined cm line
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(cpair, H * 0.10); ctx.lineTo(cpair, baseY + 4); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("cm of the pair", cpair, H * 0.07);

// table edge line
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(tableX, H * 0.10); ctx.lineTo(tableX, baseY + H * 0.20); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("edge", tableX + 4, H * 0.16);

const topOK = c2 <= x1 + L * scale + 0.01;
const pairOK = cpair <= tableX + 0.01;
ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText(topOK ? "top block: stable" : "top block: topples", W * 0.80, H * 0.28);
ctx.fillText(pairOK ? "pair: stable" : "pair: topples", W * 0.80, H * 0.44);

const total = (over1 + over2) * L;
out.note = "total overhang = " + total.toFixed(3) + " L" +
  ((topOK && pairOK) ? "   (stable; the limit is 0.500 + 0.250 = 0.750 L)" : "   (UNSTABLE)");
